import assert from "node:assert/strict";
import { test } from "node:test";
import { createCompletionsExtractionModel } from "../src/memory-extraction-model.js";
import type { ModelProviderRuntime, ResolvedModel } from "../src/model-loop/types.js";

const COMPLETIONS_MODEL: ResolvedModel = {
  providerId: "xai",
  id: "grok-4.3",
  name: "Grok 4.3",
  api: "openai-completions",
  baseUrl: "https://api.x.ai/v1",
  input: ["text", "image"],
  contextWindow: 128_000,
  maxTokens: 16_384,
};

const CODEX_MODEL: ResolvedModel = {
  providerId: "openai-codex",
  id: "gpt-5.4",
  name: "GPT-5.4",
  api: "codex-responses",
  baseUrl: "https://chatgpt.com/backend-api",
  input: ["text"],
  contextWindow: 128_000,
  maxTokens: 16_384,
};

function fakeRuntime(model: ResolvedModel): ModelProviderRuntime {
  return {
    getProvider: () => undefined,
    getAvailable: async () => [],
    checkAuth: async () => undefined,
    getAuth: async () => undefined,
    login: async () => undefined,
    logout: async () => undefined,
    resolveModel: async () => model,
    bearer: async () => "test-bearer",
    extraHeaders: async () => (
      model.api === "codex-responses" ? { "chatgpt-account-id": "acct-1" } : {}
    ),
    providerVersion: () => 1,
  };
}

const SAMPLE_INPUT = {
  providerId: "xai",
  modelId: "grok-4.3",
  utterance: "以后用要点列表回答我",
  replyText: "好的。",
  existingFacts: [],
};

test("completions providers POST /chat/completions", async () => {
  let url = "";
  let body: Record<string, unknown> = {};
  const model = createCompletionsExtractionModel(
    fakeRuntime(COMPLETIONS_MODEL),
    async (input, init) => {
      url = String(input);
      body = JSON.parse(String(init?.body)) as Record<string, unknown>;
      return new Response(
        JSON.stringify({
          choices: [{
            message: { content: '{"new_facts":["用户偏好要点列表"],"confirmed_fact_ids":[]}' },
          }],
        }),
        { status: 200 },
      );
    },
  );
  const output = await model.extract({ ...SAMPLE_INPUT });
  assert.equal(url, "https://api.x.ai/v1/chat/completions");
  assert.equal(body.stream, false);
  assert.deepEqual(output.newFacts, ["用户偏好要点列表"]);
});

test("Codex providers POST /codex/responses and read the SSE wire", async () => {
  let url = "";
  let headers: Record<string, string> = {};
  const encoder = new TextEncoder();
  const sse = [
    'data: {"type":"response.output_text.delta","delta":"{\\"new_facts\\":[],"}',
    'data: {"type":"response.output_text.delta","delta":"\\"confirmed_fact_ids\\":[]}"}',
    'data: {"type":"response.completed"}',
    "data: [DONE]",
    "",
  ].join("\n");
  const model = createCompletionsExtractionModel(
    fakeRuntime(CODEX_MODEL),
    async (input, init) => {
      url = String(input);
      headers = init?.headers as Record<string, string>;
      return new Response(
        new ReadableStream({
          start(controller) {
            controller.enqueue(encoder.encode(sse));
            controller.close();
          },
        }),
        { status: 200 },
      );
    },
  );
  const output = await model.extract({
    ...SAMPLE_INPUT,
    providerId: "openai-codex",
    modelId: "gpt-5.4",
  });
  assert.equal(url, "https://chatgpt.com/backend-api/codex/responses");
  assert.equal(headers.accept, "text/event-stream");
  assert.equal(headers["OpenAI-Beta"], "responses=experimental");
  assert.equal(headers.originator, "codex_cli_rs");
  assert.equal(headers["chatgpt-account-id"], "acct-1");
  assert.deepEqual(output, { newFacts: [], confirmedFactIds: [] });
});

/**
 * Runtime implementation of the kernel's MemoryExtractionModel port
 * (ADR 0016 #4): one-shot call on the same provider/model the completed
 * turn used, speaking that provider's wire protocol. Completions providers
 * POST /chat/completions; Codex POSTs /codex/responses.
 */

import type { ModelProviderRuntime, ResolvedModel } from "./model-loop/types.js";
import {
  buildResponsesBody,
  readResponsesEvents,
  ResponsesStreamParser,
} from "./model-loop/codex-responses.js";
import type {
  MemoryExtractionInput,
  MemoryExtractionOutput,
} from "@yishu/kernel";

const EXTRACTION_SYSTEM_PROMPT = [
  "You extract durable facts about the user from one dialogue turn.",
  "Rules:",
  "- Only stable facts or preferences (e.g. preferred format, long-term constraints, self-described habits).",
  "- Never extract task status, one-off requests, or transient context.",
  "- Never invent or infer beyond what the dialogue literally supports.",
  "- new_facts: short standalone sentences in the user's language, at most 3.",
  "- confirmed_fact_ids: ids from existing_facts this turn re-confirms.",
  'Reply with pure JSON: {"new_facts": string[], "confirmed_fact_ids": string[]}',
].join("\n");

const MAX_EXTRACTION_CHARS = 4000;

function parseExtractionJson(text: string): MemoryExtractionOutput {
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start < 0 || end <= start) {
    throw new Error("extraction model returned no JSON object");
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text.slice(start, end + 1));
  } catch {
    throw new Error("extraction model returned invalid JSON");
  }
  if (typeof parsed !== "object" || parsed === null) {
    throw new Error("extraction model returned invalid JSON");
  }
  const record = parsed as Record<string, unknown>;
  const newFacts = Array.isArray(record.new_facts)
    ? record.new_facts.filter((fact: unknown): fact is string =>
        typeof fact === "string" && fact.trim().length > 0)
    : [];
  const confirmed = Array.isArray(record.confirmed_fact_ids)
    ? record.confirmed_fact_ids.filter((fact: unknown): fact is string =>
        typeof fact === "string")
    : [];
  return { newFacts: newFacts.slice(0, 3), confirmedFactIds: confirmed };
}

function userPayload(input: MemoryExtractionInput): string {
  const existing = input.existingFacts.length === 0
    ? "(none)"
    : input.existingFacts.map((f) => `${f.id}: ${f.claim}`).join("\n");
  return [
    `USER SAID: ${input.utterance.slice(0, MAX_EXTRACTION_CHARS)}`,
    `ASSISTANT REPLIED: ${input.replyText.slice(0, MAX_EXTRACTION_CHARS)}`,
    `EXISTING FACTS:\n${existing}`,
  ].join("\n\n");
}

async function extractViaCompletions(
  model: ResolvedModel,
  payload: string,
  headers: Record<string, string>,
  fetchImpl: typeof fetch,
): Promise<string> {
  const response = await fetchImpl(
    `${model.baseUrl.replace(/\/$/, "")}/chat/completions`,
    {
      method: "POST",
      headers,
      body: JSON.stringify({
        model: model.id,
        messages: [
          { role: "system", content: EXTRACTION_SYSTEM_PROMPT },
          { role: "user", content: payload },
        ],
        stream: false,
        max_tokens: 512,
      }),
    },
  );
  if (!response.ok) {
    throw new Error(`extraction model call failed (${response.status})`);
  }
  const body = (await response.json()) as {
    choices?: Array<{ message?: { content?: string } }>;
  };
  return body.choices?.[0]?.message?.content ?? "";
}

async function extractViaCodexResponses(
  model: ResolvedModel,
  payload: string,
  headers: Record<string, string>,
  fetchImpl: typeof fetch,
): Promise<string> {
  const body = buildResponsesBody(
    model,
    EXTRACTION_SYSTEM_PROMPT,
    [{ role: "user", text: payload }],
    [],
  );
  const response = await fetchImpl(
    `${model.baseUrl.replace(/\/$/, "")}/codex/responses`,
    {
      method: "POST",
      headers: {
        ...headers,
        accept: "text/event-stream",
        "OpenAI-Beta": "responses=experimental",
        originator: "codex_cli_rs",
      },
      body: JSON.stringify(body),
    },
  );
  if (!response.ok) {
    throw new Error(`extraction model call failed (${response.status})`);
  }
  if (!response.body) {
    throw new Error("extraction model response has no body");
  }
  const parser = new ResponsesStreamParser();
  let text = "";
  for await (const event of readResponsesEvents(response.body)) {
    const piece = parser.push(event);
    if (piece?.type === "text_delta") text += piece.delta;
    if (piece?.type === "message_done") break;
  }
  return text;
}

export function createCompletionsExtractionModel(
  providerRuntime: ModelProviderRuntime,
  fetchImpl: typeof fetch = fetch,
): {
  extract: (input: MemoryExtractionInput) => Promise<MemoryExtractionOutput>;
} {
  return {
    async extract(input: MemoryExtractionInput): Promise<MemoryExtractionOutput> {
      const model = await providerRuntime.resolveModel(input.providerId, input.modelId);
      const bearer = await providerRuntime.bearer(model.providerId);
      const headers: Record<string, string> = {
        "content-type": "application/json",
        authorization: `Bearer ${bearer}`,
        ...(await providerRuntime.extraHeaders(model.providerId)),
      };
      const payload = userPayload(input);
      const text = model.api === "codex-responses"
        ? await extractViaCodexResponses(model, payload, headers, fetchImpl)
        : await extractViaCompletions(model, payload, headers, fetchImpl);
      return parseExtractionJson(text);
    },
  };
}

/**
 * OpenAI Codex Responses wire adapter (ADR 0014).
 *
 * Talks to `https://chatgpt.com/backend-api/codex/responses` with the
 * subscription OAuth bearer plus `chatgpt-account-id`. Handles the events
 * the loop needs: `response.output_text.delta`,
 * `response.output_item.done` (message / function_call), `response.completed`
 * and stream errors.
 */

import type { AnyToolDefinition, CanonicalMessage, PromptImage, ResolvedModel } from "./types.js";
import { readSseData, type WireToolCall } from "./openai-completions.js";

export type ResponsesStreamPiece =
  | { type: "text_delta"; delta: string }
  | { type: "message_done"; finishReason: string | null; toolCalls: readonly WireToolCall[] };

export type ResponsesMessageDone = Extract<ResponsesStreamPiece, { type: "message_done" }>;

function inputItemFor(item: CanonicalMessage): Record<string, unknown> | undefined {
  switch (item.role) {
    case "user": {
      const content: Array<Record<string, unknown>> = [];
      if (item.text) content.push({ type: "input_text", text: item.text });
      for (const image of item.images ?? []) {
        content.push({
          type: "input_image",
          image_url: `data:${image.mimeType};base64,${image.data}`,
        });
        if (image.label !== undefined && image.label.length > 0) {
          content.push({ type: "input_text", text: image.label });
        }
      }
      return { type: "message", role: "user", content };
    }
    case "assistant":
      return item.toolCalls.length > 0
        ? {
          type: "message",
          role: "assistant",
          content: item.text ? [{ type: "output_text", text: item.text }] : [],
          // Function calls are replayed as siblings in the input array.
          siblingCalls: item.toolCalls.map((call) => ({
            type: "function_call",
            call_id: call.id,
            name: call.name,
            arguments: call.argumentsJson,
          })),
        }
        : {
          type: "message",
          role: "assistant",
          content: [{ type: "output_text", text: item.text }],
        };
    case "tool":
      return {
        type: "function_call_output",
        call_id: item.callId,
        output: item.output,
      };
    case "system":
      return undefined;
  }
}

export function buildResponsesBody(
  model: ResolvedModel,
  systemPrompt: string,
  history: readonly CanonicalMessage[],
  activeTools: readonly AnyToolDefinition[],
  transientTail?: { role: "user"; text: string },
): Record<string, unknown> {
  const input: Array<Record<string, unknown>> = [];
  for (const item of history) {
    const wire = inputItemFor(item);
    if (!wire) continue;
    const siblingCalls = (wire as { siblingCalls?: Array<Record<string, unknown>> }).siblingCalls;
    delete (wire as { siblingCalls?: unknown }).siblingCalls;
    input.push(wire);
    for (const call of siblingCalls ?? []) input.push(call);
  }
  if (transientTail) {
    input.push({ type: "message", role: "user", content: [{ type: "input_text", text: transientTail.text }] });
  }
  const body: Record<string, unknown> = {
    model: model.id,
    instructions: systemPrompt,
    input,
    stream: true,
    max_output_tokens: model.maxTokens,
  };
  if (activeTools.length > 0) {
    body.tools = activeTools.map((tool) => ({
      type: "function",
      name: tool.name,
      description: tool.description,
      parameters: tool.parameters,
      strict: false,
    }));
  }
  return body;
}

interface ResponsesStreamEvent {
  type?: string;
  delta?: string;
  item?: {
    type?: string;
    call_id?: string;
    name?: string;
    arguments?: string;
  };
  response?: { error?: unknown };
  message?: string;
}

export class ResponsesStreamParser {
  private done = false;
  private readonly toolCalls: WireToolCall[] = [];

  push(event: ResponsesStreamEvent): ResponsesStreamPiece | undefined {
    if (this.done) return undefined;
    switch (event.type) {
      case "response.output_text.delta":
        if (typeof event.delta === "string" && event.delta.length > 0) {
          return { type: "text_delta", delta: event.delta };
        }
        return undefined;
      case "response.output_item.done":
        if (event.item?.type === "function_call"
          && typeof event.item.call_id === "string"
          && typeof event.item.name === "string") {
          this.toolCalls.push({
            id: event.item.call_id,
            name: event.item.name,
            argumentsJson: typeof event.item.arguments === "string" ? event.item.arguments : "",
          });
        }
        return undefined;
      case "response.completed":
      case "response.failed":
      case "response.incomplete":
      case "error": {
        this.done = true;
        const finishReason = this.toolCalls.length > 0 ? "tool_calls" : "stop";
        if (event.type === "error" || event.type === "response.failed") {
          const detail = event.message
            ?? (event.response?.error instanceof Error ? event.response.error.message : undefined);
          if (detail) throw new Error(String(detail));
        }
        return { type: "message_done", finishReason, toolCalls: [...this.toolCalls] };
      }
      default:
        return undefined;
    }
  }

  finish(): ResponsesMessageDone {
    if (this.done) return { type: "message_done", finishReason: "stop", toolCalls: [] };
    this.done = true;
    return {
      type: "message_done",
      finishReason: this.toolCalls.length > 0 ? "tool_calls" : "stop",
      toolCalls: [...this.toolCalls],
    };
  }
}

export async function* readResponsesEvents(
  body: ReadableStream<Uint8Array>,
  signal?: AbortSignal,
): AsyncGenerator<ResponsesStreamEvent> {
  for await (const payload of readSseData(body, signal)) {
    if (payload === "[DONE]") return;
    try {
      yield JSON.parse(payload) as ResponsesStreamEvent;
    } catch {
      // Ignore keep-alive or malformed lines.
    }
  }
}

/**
 * OpenAI-compatible chat/completions wire adapter (ADR 0014).
 *
 * Covers the local Grok loopback (8787) and xAI. Consumes the streaming
 * SSE shape `choices[0].delta.content` / `delta.tool_calls` /
 * `finish_reason`, which the loopback forwards verbatim.
 */

import type { AnyToolDefinition, CanonicalMessage, PromptImage, ResolvedModel } from "./types.js";

export interface CompletionsRequestBody {
  model: string;
  messages: Array<Record<string, unknown>>;
  tools?: Array<Record<string, unknown>>;
  stream: boolean;
  max_tokens: number;
}

export interface WireToolCall {
  id: string;
  name: string;
  argumentsJson: string;
}

export type CompletionsStreamPiece =
  | { type: "text_delta"; delta: string }
  | { type: "message_done"; finishReason: string | null; toolCalls: readonly WireToolCall[] };

export type CompletionsMessageDone = Extract<CompletionsStreamPiece, { type: "message_done" }>;

interface AccumulatedToolCall {
  index: number;
  id?: string;
  name?: string;
  argumentBuffer: string;
}

function userContent(text: string, images?: readonly PromptImage[]): unknown {
  if (!images || images.length === 0) return text;
  const parts: Array<Record<string, unknown>> = [];
  if (text.length > 0) parts.push({ type: "text", text });
  for (const image of images) {
    parts.push({
      type: "image_url",
      image_url: { url: `data:${image.mimeType};base64,${image.data}` },
    });
    if (image.label !== undefined && image.label.length > 0) {
      parts.push({ type: "text", text: image.label });
    }
  }
  return parts;
}

export interface TransientTailMessage {
  readonly role: "user";
  readonly text: string;
}

export function buildCompletionsBody(
  model: ResolvedModel,
  systemPrompt: string,
  history: readonly CanonicalMessage[],
  activeTools: readonly AnyToolDefinition[],
  transientTail?: TransientTailMessage,
): CompletionsRequestBody {
  const messages: Array<Record<string, unknown>> = [
    { role: "system", content: systemPrompt },
    ...history.map((item): Record<string, unknown> => {
      switch (item.role) {
        case "user":
          return { role: "user", content: userContent(item.text, item.images) };
        case "assistant":
          return item.toolCalls.length > 0
            ? {
              role: "assistant",
              content: item.text || null,
              tool_calls: item.toolCalls.map((call) => ({
                id: call.id,
                type: "function",
                function: { name: call.name, arguments: call.argumentsJson },
              })),
            }
            : { role: "assistant", content: item.text };
        case "tool":
          return {
            role: "tool",
            tool_call_id: item.callId,
            content: item.output,
          };
        case "system":
          return { role: "system", content: item.text };
      }
    }),
    ...(transientTail ? [{ role: "user", content: transientTail.text }] : []),
  ];
  const body: CompletionsRequestBody = {
    model: model.id,
    messages,
    stream: true,
    max_tokens: model.maxTokens,
  };
  if (activeTools.length > 0) {
    body.tools = activeTools.map((tool) => ({
      type: "function",
      function: {
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters,
      },
    }));
  }
  return body;
}

/**
 * Incremental SSE consumer. Feed each `data:` payload (without the
 * `data: ` prefix); it emits text deltas and, on `[DONE]` or a terminal
 * chunk, the assembled tool calls.
 */
export class CompletionsStreamParser {
  private text = "";
  private readonly toolCalls = new Map<number, AccumulatedToolCall>();
  private finishReason: string | null = null;
  private done = false;

  push(payload: string): CompletionsStreamPiece | undefined {
    if (this.done) return undefined;
    if (payload === "[DONE]") {
      this.done = true;
      return { type: "message_done", finishReason: this.finishReason, toolCalls: this.snapshot() };
    }
    let chunk: {
      choices?: Array<{
        finish_reason?: string | null;
        delta?: { content?: string | null; tool_calls?: Array<{
          index?: number;
          id?: string;
          function?: { name?: string; arguments?: string };
        }> };
      }>;
    };
    try {
      chunk = JSON.parse(payload);
    } catch {
      return undefined;
    }
    const choice = chunk.choices?.[0];
    if (!choice) return undefined;
    if (typeof choice.finish_reason === "string") this.finishReason = choice.finish_reason;
    const delta = choice.delta?.content;
    let piece: CompletionsStreamPiece | undefined;
    if (typeof delta === "string" && delta.length > 0) {
      this.text += delta;
      piece = { type: "text_delta", delta };
    }
    for (const call of choice.delta?.tool_calls ?? []) {
      const index = call.index ?? 0;
      let accumulated = this.toolCalls.get(index);
      if (!accumulated) {
        accumulated = { index, argumentBuffer: "" };
        this.toolCalls.set(index, accumulated);
      }
      if (call.id) accumulated.id = call.id;
      if (call.function?.name) accumulated.name = call.function.name;
      if (call.function?.arguments) accumulated.argumentBuffer += call.function.arguments;
    }
    if (choice.finish_reason !== null && choice.finish_reason !== undefined) {
      this.done = true;
      return { type: "message_done", finishReason: this.finishReason, toolCalls: this.snapshot() };
    }
    return piece;
  }

  finish(): CompletionsMessageDone {
    if (this.done) return { type: "message_done", finishReason: this.finishReason, toolCalls: [] };
    this.done = true;
    return { type: "message_done", finishReason: this.finishReason, toolCalls: this.snapshot() };
  }

  private snapshot(): readonly WireToolCall[] {
    return [...this.toolCalls.values()]
      .sort((a, b) => a.index - b.index)
      .filter((call): call is AccumulatedToolCall & { id: string; name: string } =>
        Boolean(call.id && call.name))
      .map((call) => ({ id: call.id, name: call.name, argumentsJson: call.argumentBuffer }));
  }
}

/** Reads one SSE stream and yields each data payload string. */
export async function* readSseData(
  body: ReadableStream<Uint8Array>,
  signal?: AbortSignal,
): AsyncGenerator<string> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  const aborted = (): Error => new Error("Model stream aborted");
  const onAbort = (): void => {
    void reader.cancel().catch(() => undefined);
  };
  if (signal?.aborted) throw aborted();
  signal?.addEventListener("abort", onAbort, { once: true });
  try {
    while (true) {
      if (signal?.aborted) throw aborted();
      const { done, value } = await reader.read();
      if (signal?.aborted) throw aborted();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      let newlineIndex = buffer.indexOf("\n");
      while (newlineIndex >= 0) {
        const line = buffer.slice(0, newlineIndex).replace(/\r$/, "");
        buffer = buffer.slice(newlineIndex + 1);
        if (line.startsWith("data:")) {
          yield line.slice(5).trimStart();
        }
        newlineIndex = buffer.indexOf("\n");
      }
    }
  } finally {
    signal?.removeEventListener("abort", onAbort);
    try {
      reader.releaseLock();
    } catch {
      // cancel() may already have released the lock
    }
  }
}
